-- =============================================================================
-- 20261016m_qa_blog_top10_nl.sql — NÁVRH ke schválení (QA brána 2026-10-16), neaplikováno
-- Blog „Top 10 dárků pro motorkáře, které skutečně potěší“ (cms_pages c84d8e65-eb6e-4bd8-bf11-cf3256ae3dd0): překlad nl je celý
-- FRANCOUZSKY (titulek „Top 10 cadeaux pour motards…“, perex i článek) → nl /blog (karta) i detail článku.
-- Nahrazuje se nizozemským překladem aktuálního českého článku (struktura HTML 1:1, oslovení „je“ jako
-- ostatní nl články). Alternativa bez SQL: Velín → Blog → článek → Uložit (auto-překlad všech 7 jazyků).
-- Bezpečnost: mění jen když nl má PŘESNĚ francouzské znění ověřené 2026-10-16 (md5 titulku, perexu i článku)
-- a český článek je stále ten, ze kterého se překládalo (md5); jinak NOTICE. Ostatní jazyky beze změny.
-- Idempotentní. Bez BEGIN/COMMIT.
-- =============================================================================
DO $$
DECLARE
  c_title constant text := $t$Top 10 cadeaus voor motorrijders waar ze echt blij mee zijn$t$;
  c_excerpt constant text := $t$Op zoek naar een cadeau voor een motorrijder dat niet alleen stof gaat verzamelen?$t$;
  c_content constant text := $t$<section aria-labelledby="blog-content"><p>Een cadeau kiezen voor een motorrijder kan een flinke uitdaging zijn.&nbsp;</p><p>Dat geldt zowel voor volwassen liefhebbers als voor kleine motorrijders die de wereld op twee wielen nog maar net ontdekken. Wil je niet weer de zoveelste “verplichte” mok met een motor, bikerstickers of een hoodie met logo geven, dan ben je hier aan het juiste adres.</p><p>We hebben voor je een overzicht gemaakt van de 10 beste cadeaus voor grote en kleine motorrijders die één ding gemeen hebben – het zijn geen stofvangers, maar dingen die liefhebbers van het motorrijden echt gebruiken en waarderen. Van kleinigheden voor een paar honderd kronen tot waardevollere cadeaus van enkele duizenden kronen.</p><p>Of je nu een cadeau zoekt voor een verjaardag, kerst, een jubileum of gewoon om iemand blij te maken, in onze lijst vind je inspiratie voor cadeaus voor zowel beginners als ervaren rijders.</p><p><span style="font-size: 1.2em; font-weight: 800;">Mini-gids – Hoe kies je een geschikt cadeau?</span></p></section><section aria-labelledby="blog-content2"><p>Om een leuk cadeau voor een motorrijder te kiezen, hoef je niet alle merken of typen motoren te kennen. Het is genoeg om een paar eenvoudige vragen te beantwoorden die je in de juiste richting sturen:</p><p><span style="font-size: 1.2em; font-weight: 700;">1. Voor wie kies je het cadeau?</span></p><p><strong>Het maakt verschil of je een cadeau kiest voor:</strong></p><p>een volwassen, actieve rijder,</p><p>iemand die af en toe motorrijdt,</p><p>een klein kind.</p><p>Bij volwassenen loont het om je te richten op praktische accessoires, uitrusting of belevenissen.</p><p>Bij kinderen&nbsp;<strong>speelt de leeftijd een grote rol&nbsp;</strong>en ook of ze zelf al rijden of voorlopig alleen fan zijn.</p><p><strong>Kinderen tot 3 jaar maak je meestal blij met:</strong></p><p>een kartonboekje, prentenboek of stickerboek over motoren,</p><p>een knuffelmotor,</p><p>een loopmotor voor de allerkleinsten,</p><p>een kussentje, dekentje of pyjama met motoren,</p><p>een kleine speelgoedmotor.</p><p><strong>Kinderen van 4 tot 10 jaar zijn misschien blij met:</strong></p><p>kleding met een motorthema,</p><p>beschermers en motoruitrusting (als ze al rijden),</p><p>een hanenkam voor op de helm,</p><p>een op afstand bestuurbare motor,</p><p>lego en bouwsets met motoren,</p><p>puzzels met motoren,</p><p>schoolspullen met een motorthema.</p><p><strong>Kinderen ouder dan 10 jaar zijn blij met:</strong></p><p>een racegame voor de computer of console,</p><p>kaartjes voor races of beurzen,</p><p>een eigen motor,</p><p>motoruitrusting,</p><p>een telefoonhoesje met een motormotief.</p><p>&nbsp;</p><h3>2. Wat is je budget voor het cadeau?</h3><p>Het is goed om meteen aan het begin te bepalen hoeveel je in het cadeau wilt investeren:</p><p>tot 500 Kč – kleinigheden, accessoires, boeken, kleding,</p><p>500 – 2000 Kč – kwalitatief goede accessoires, uitrusting,</p><p>boven 2 000 Kč – elektronica, duurdere uitrusting, cadeaubonnen voor belevenissen.</p><p><span style="font-size: 1.2em; font-weight: 700;">3. Geef je liever iets tastbaars of een belevenis?</span></p><p>Sommige mensen waarderen eerder een tastbaar cadeau, anderen onthouden vooral bijzondere momenten. Bijvoorbeeld hun eerste rit op een motor of het uitproberen van een nieuwe machine.</p><p><span style="font-weight: bold;">Twijfel je nog, dan is het altijd veiliger om voor universele accessoires of een cadeaubon te kiezen. Zo verklein je de kans dat je de plank misslaat.</span></p><p><span style="font-size: 1.2em; font-weight: 700;">Top 10 cadeaus voor volwassen rijders</span></p><ol><li><strong>Cadeaubon voor het huren van een motor of een belevenisrit</strong><br>Een van de meest universele cadeaus voor zowel beginnende als ervaren motorrijders. De kans om een ander type motor uit te proberen of de droom waar te maken om op een bepaalde machine te rijden, is een belevenis die je niet vergeet.</li><li><strong>Telefoonhouder voor de motor</strong><br>Een handig accessoire voor navigatie en om snel de route te checken. Past bij vrijwel elke rijder en hoort bij de populairste motorcadeaus.</li><li><strong>Intercom voor in de helm</strong><br>Maakt communicatie mogelijk met de duopassagier en andere rijders, en laat je naar navigatie of muziek luisteren. Een geweldig cadeau voor wie regelmatig rijdt.</li><li><strong>Touchscreen- of verwarmde handschoenen</strong><br>Verhogen het comfort tijdens het rijden. De rijder hoeft zijn handschoenen niet uit te trekken om zijn telefoon te bedienen. Verwarmde handschoenen komen goed van pas bij kouder weer en zijn dus vooral geschikt voor wie vrijwel het hele jaar rijdt.</li><li><strong>EHBO-set voor motorrijders</strong><br>Klein, compact en heel praktisch. Elke motorrijder zou er een bij zich moeten hebben. Ideaal als cadeau dat ooit echt kan helpen.</li><li><strong>Bagagenet en spanbanden</strong><br>Perfecte hulp om een rugzak, helm of kleinere spullen vast te zetten waarvoor je geen plek meer hebt in de koffer.</li><li><strong>Kettingslot of andere beveiliging voor de motor</strong><br>Beveiliging is de basis. Een goed slot is nooit overbodig en bespaart een motorrijder heel wat narigheid.</li><li><strong>Camera voor op de helm of de motor</strong><br>Hiermee leg je ritten, uitstapjes en het dagelijkse rijden vast – en hij dient ook als waardevol bewijs bij een ongeval of een betwiste situatie.</li><li><strong>Cadeaupakket met motorverzorgingsproducten</strong><br>Voor rijders die hun motor graag schoon en goed verzorgd houden. Een praktisch en tegelijk mooi cadeau.</li><li><strong>Motorhoes</strong><br>Beschermt de motor tegen regen, stof en zon, of hij nu in de garage of buiten staat.</li></ol><p>&nbsp;</p><h3>Top 10 cadeaus voor kleine motorliefhebbers</h3><ol><li><strong>Schoolspullen met een motormotief</strong><br>Rugzak, etui, gymtas, broodtrommel of drinkfles. Er bestaan enorm veel ontwerpen, dus elke kleine motorrijder vindt wel iets. Bovendien is het een geweldige manier om kinderen zin te geven in school.</li><li><strong>Cadeauset met schrijfwaren in motordesign</strong><br>Potloden, kleurpotloden, een notitieblokje, puntenslijper of liniaal met motoren. Geschikt voor kleuters en schoolkinderen, voor thuis en op school.</li><li><strong>Kaartje voor een motorcrosswedstrijd, een wegrace-GP of een motorbeurs</strong><br>Geef een originele belevenis waar kinderen nog lang aan terugdenken.</li><li><strong>Loopmotor in motorstijl of een eerste elektrische kindermotor</strong><br>Een ideaal cadeau voor de allerkleinsten als eerste stap in de wereld van motorrijders. Ontwikkelt evenwicht en coördinatie en wakkert het rijplezier aan.</li><li><strong>Kleding met een motormotief</strong><br>Leuk en praktisch in één. Een schot in de roos voor kind én ouders.</li><li><strong>Motorkussentje, motordekbedovertrek of pyjama</strong><br>Een zinvol cadeau dat je kind elke avond voor het slapengaan blij maakt en meeneemt naar de wereld van motordromen.</li><li><strong>Puzzel, lego of bouwset met een motorthema</strong><br>Een geweldig cadeau voor kleine bouwers en makers.</li><li><strong>Boeken over motoren, kartonboekjes, stickerboeken</strong><br>Voor de allerkleinsten prentenboeken met harde kaft, interactieve elementen of kartonboekjes. Voor oudere kinderen verhalen over motoren en avonturen, of motorencyclopedieën.</li><li><strong>Racegame voor pc of console</strong><br>Een leuk cadeau voor oudere kinderen en tieners, waarin de liefde voor computergames en de wereld van motoren samenkomen.</li><li><strong>Kleine speelgoedmotor, op afstand bestuurbare motor</strong><br>Een miniversie van een motor om mee te spelen of op afstand te besturen is een geweldig cadeau voor kinderen die naar een eigen machine verlangen. Ideaal om binnen en buiten mee te spelen.</li></ol><h3>Tot slot</h3><p>Of je nu kiest voor een praktisch accessoire of een belevenis in de vorm van een motorrit, het belangrijkste is het plezier van het ontdekken en de vrijheid die de wereld op twee wielen biedt.</p><p>Wil je iets echt bijzonders geven, dan is een cadeaubon voor het huren van een motor bij MotoGo24 een geweldige keuze voor iedereen. ;)</p></section>$t$;
  n integer;
BEGIN
  IF EXISTS (SELECT 1 FROM public.cms_pages WHERE id = 'c84d8e65-eb6e-4bd8-bf11-cf3256ae3dd0'
              AND translations -> 'nl' ->> 'title' = c_title AND translations -> 'nl' ->> 'content' = c_content) THEN
    RAISE NOTICE 'blog top-10 nl: už hotovo';
    RETURN;
  END IF;
  UPDATE public.cms_pages
     SET translations = jsonb_set(translations, '{nl}',
           (translations -> 'nl') || jsonb_build_object('title', c_title, 'excerpt', c_excerpt, 'content', c_content))
   WHERE id = 'c84d8e65-eb6e-4bd8-bf11-cf3256ae3dd0'
     AND md5(translations -> 'nl' ->> 'title') = 'ef64d5f81b4236c204809c1a755511ea'
     AND md5(translations -> 'nl' ->> 'excerpt') = 'c531d4bea9c7b5c73e26111c65f0291f'
     AND md5(translations -> 'nl' ->> 'content') = '222cc9c63b7ec410154ca05f969877e3'
     AND md5(title) = '9a31c4439dad5519effb2cb657c3078c'
     AND md5(content) = 'a8c2d535a42c6b9107048709976af0f9';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n = 1 THEN RAISE NOTICE 'blog top-10 nl: nizozemský překlad uložen';
  ELSE RAISE NOTICE 'blog top-10 nl: překlad nebo český článek se liší od ověřeného (Velín?) – beze změny';
  END IF;
END $$;
